package com.mediconnect.appointment.domain;
import java.time.Instant; import java.util.UUID; import com.mediconnect.doctor.domain.DoctorEntity; import com.mediconnect.office.domain.OfficeEntity; import com.mediconnect.patient.domain.PatientEntity; import com.mediconnect.shared.audit.AuditableEntity; import jakarta.persistence.*;
@Entity @Table(name="appointments",indexes={@Index(name="idx_appointments_doctor_time",columnList="doctor_id,start_time,end_time"),@Index(name="idx_appointments_patient",columnList="patient_id")}) public class AppointmentEntity extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id",nullable=false) private PatientEntity patient; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="doctor_id",nullable=false) private DoctorEntity doctor; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="office_id",nullable=false) private OfficeEntity office; @Column(name="start_time",nullable=false) private Instant startTime; @Column(name="end_time",nullable=false) private Instant endTime; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private AppointmentStatus status=AppointmentStatus.SCHEDULED; @Version private long version; protected AppointmentEntity(){} public AppointmentEntity(PatientEntity patient,DoctorEntity doctor,OfficeEntity office,Instant startTime,Instant endTime){this.patient=patient;this.doctor=doctor;this.office=office;this.startTime=startTime;this.endTime=endTime;this.status=AppointmentStatus.SCHEDULED;} public UUID getId(){return id;} public PatientEntity getPatient(){return patient;} public DoctorEntity getDoctor(){return doctor;} public OfficeEntity getOffice(){return office;} public Instant getStartTime(){return startTime;} public Instant getEndTime(){return endTime;} public AppointmentStatus getStatus(){return status;} public long getVersion(){return version;} public void cancel(){status=AppointmentStatus.CANCELLED;} public void complete(){status=AppointmentStatus.COMPLETED;} }
